import{_ as r,a0 as l,w as d,s as a,I as n,x as t,a1 as i,A as p,ao as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"RHCSA 系列（十三）： 在 RHEL 7 中使用 SELinux 進行強制訪問控制 | LCTT x X-CMD","titleTemplate":false,"description":"RHCSA 系列（十三）： 在 RHEL 7 中使用 SELinux 進行強制訪問控制 | LCTT (RHCSA Series) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"RHCSA 系列（十三）： 在 RHEL 7 中使用 SELinux 進行強制訪問控制 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"RHCSA 系列（十三）： 在 RHEL 7 中使用 SELinux 進行強制訪問控制 | LCTT (RHCSA Series) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"RHCSA Series/RHCSA Series--Part 13--Mandatory Access Control Essentials with SELinux in RHEL 7","title":"RHCSA 系列（十三）： 在 RHEL 7 中使用 SELinux 進行強制訪問控制","tag":"RHCSA Series","desc":""},"relativePath":"RHCSA Series/RHCSA Series--Part 13--Mandatory Access Control Essentials with SELinux in RHEL 7.md","filePath":"[post].md"}'),u={name:"RHCSA Series/RHCSA Series--Part 13--Mandatory Access Control Essentials with SELinux in RHEL 7.md"};function S(m,e,x,L,E,g){const s=l("Link");return d(),a("div",null,[e[33]||(e[33]=n("h1",{id:"rhcsa-系列-十三-在-rhel-7-中使用-selinux-進行強制訪問控制",tabindex:"-1"},[t("RHCSA 系列（十三）： 在 RHEL 7 中使用 SELinux 進行強制訪問控制 "),n("a",{class:"header-anchor",href:"#rhcsa-系列-十三-在-rhel-7-中使用-selinux-進行強制訪問控制","aria-label":"Permalink to “RHCSA 系列（十三）： 在 RHEL 7 中使用 SELinux 進行強制訪問控制”"},"​")],-1)),n("p",null,[e[2]||(e[2]=t("在本系列的前面幾篇文章中，我們已經詳細地探索了至少兩種訪問控制方法：標準的 ugo/rwx 權限（",-1)),i(s,{href:"https://linux.cn/article-6187-1.html"},{default:p(()=>[...e[0]||(e[0]=[t("RHCSA 系列（三）: 如何管理 RHEL7 的用户和組",-1)])]),_:1}),e[3]||(e[3]=t("） 和訪問控制列表（",-1)),i(s,{href:"https://linux.cn/article-6263-1.html"},{default:p(()=>[...e[1]||(e[1]=[t("RHCSA 系列（七）: 使用 ACL（訪問控制列表) 和掛載 Samba/NFS 共享",-1)])]),_:1}),e[4]||(e[4]=t("）。",-1))]),e[34]||(e[34]=o(`<p><img src="http://www.tecmint.com/wp-content/uploads/2015/06/SELinux-Control-File-System-Access.png" alt="RHCSA 認證：SELinux 精要和控制文件系統的訪問"></p><p><em>RHCSA 認證：SELinux 精要和控制文件系統的訪問</em></p><p>儘管作為第一級別的權限和訪問控制機制是必要的，但它們同樣有一些侷限，而這些侷限則可以由安全增強 Linux(Security Enhanced Linux，簡稱為 SELinux) 來處理。</p><p>這些侷限的一種情形是：某個用户可能通過一個泛泛的 chmod 命令將文件或目錄暴露出現了安全違例，從而引起訪問權限的意外傳播。結果，由該用户開啓的任意進程可以對屬於該用户的文件進行任意的操作，最終一個惡意的或有其它缺陷的軟件可能會取得整個系統的 root 級別的訪問權限。</p><p>考慮到這些侷限性，美國國家安全局（NSA） 率先設計出了 SELinux，一種強制的訪問控制方法，它根據最小權限模型去限制進程在系統對象（如文件，目錄，網絡接口等）上的訪問或執行其他的操作的能力，而這些限制可以在之後根據需要進行修改。簡單來説，系統的每一個元素只給某個功能所需要的那些權限。</p><p>在 RHEL 7 中，SELinux 被併入了內核中，且默認情況下以強制模式（Enforcing）開啓。在這篇文章中，我們將簡要地介紹有關 SELinux 及其相關操作的基本概念。</p><h3 id="selinux-的模式" tabindex="-1">SELinux 的模式 <a class="header-anchor" href="#selinux-的模式" aria-label="Permalink to “SELinux 的模式”">​</a></h3><p>SELinux 可以以三種不同的模式運行：</p><ul><li>強制模式（Enforcing）：SELinux 基於其策略規則來拒絕訪問，這些規則是用以控制安全引擎的一系列準則；</li><li>寬容模式（Permissive）：SELinux 不會拒絕訪問，但對於那些如果運行在強制模式下會被拒絕訪問的行為進行記錄；</li><li>關閉（Disabled） (不言自明，即 SELinux 沒有實際運行).</li></ul><p>使用 <code>getenforce</code> 命令可以展示 SELinux 當前所處的模式，而 <code>setenforce</code> 命令（後面跟上一個 1 或 0） 則被用來將當前模式切換到強制模式（Enforcing）或寬容模式（Permissive），但只對當前的會話有效。</p><p>為了使得在登出和重啓後上面的設置還能保持作用，你需要編輯 <code>/etc/selinux/config</code> 文件並將 SELINUX 變量的值設為 enforcing，permissive，disabled 中之一：</p><pre><code># getenforce
# setenforce 0
# getenforce
# setenforce 1
# getenforce
# cat /etc/selinux/config
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Set-SELinux-Mode.png" alt="設置 SELinux 模式"></p><p><em>設置 SELinux 模式</em></p><p>通常情況下，你應該使用 <code>setenforce</code> 來在 SELinux 模式間進行切換（從強制模式到寬容模式，或反之），以此來作為你排錯的第一步。假如 SELinux 當前被設置為強制模式，而你遇到了某些問題，但當你把 SELinux 切換為寬容模式後問題不再出現了，則你可以確信你遇到了一個 SELinux 權限方面的問題。</p><h3 id="selinux-上下文" tabindex="-1">SELinux 上下文 <a class="header-anchor" href="#selinux-上下文" aria-label="Permalink to “SELinux 上下文”">​</a></h3><p>一個 SELinux 上下文（Context）由一個訪問控制環境所組成，在這個環境中，決定的做出將基於 SELinux 的用户，角色和類型（和可選的級別）：</p><ul><li>一個 SELinux 用户是通過將一個常規的 Linux 用户賬户映射到一個 SELinux 用户賬户來實現的，反過來，在一個會話中，這個 SELinux 用户賬户在 SELinux 上下文中被進程所使用，以便能夠明確定義它們所允許的角色和級別。</li><li>角色的概念是作為域和處於該域中的 SELinux 用户之間的媒介，它定義了 SELinux 可以訪問到哪個進程域和哪些文件類型。這將保護您的系統免受提權漏洞的攻擊。</li><li>類型則定義了一個 SELinux 文件類型或一個 SELinux 進程域。在正常情況下，進程將會被禁止訪問其他進程正使用的文件，並禁止對其他進程進行訪問。這樣只有當一個特定的 SELinux 策略規則允許它訪問時，才能夠進行訪問。</li></ul><p>下面就讓我們看看這些概念是如何在下面的例子中起作用的。</p><p><strong>例 1：改變 sshd 守護進程的默認端口</strong></p>`,20)),n("p",null,[e[6]||(e[6]=t("在 ",-1)),i(s,{href:"https://linux.cn/article-6266-1.html"},{default:p(()=>[...e[5]||(e[5]=[t("RHCSA 系列（八）: 加固 SSH，設定主機名及啓用網絡服務",-1)])]),_:1}),e[7]||(e[7]=t(" 中，我們解釋了更改 sshd 所監聽的默認端口是加固你的服務器免受外部攻擊的首要安全措施。下面，就讓我們編輯 ",-1)),e[8]||(e[8]=n("code",null,"/etc/ssh/sshd_config",-1)),e[9]||(e[9]=t(" 文件並將端口設置為 9999：",-1))]),e[35]||(e[35]=o(`<pre><code>Port 9999
</code></pre><p>保存更改並重啓 sshd：</p><pre><code># systemctl restart sshd
# systemctl status sshd
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Change-SSH-Port.png" alt="更改 SSH 的端口"></p><p><em>重啓 SSH 服務</em></p><p>正如你看到的那樣， sshd 啓動失敗，但為什麼會這樣呢？</p><p>快速檢查 <code>/var/log/audit/audit.log</code> 文件會發現 sshd 已經被拒絕在端口 9999 上開啓（SELinux 的日誌信息包含單詞 &quot;AVC&quot;，所以這類信息可以被輕易地與其他信息相區分），因為這個端口是 JBoss 管理服務的保留端口：</p><pre><code># cat /var/log/audit/audit.log | grep AVC | tail -1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Inspect-SSH-Logs.png" alt="查看 SSH 日誌"></p><p><em>查看 SSH 日誌</em></p><p>在這種情況下，你可以像先前解釋的那樣禁用 SELinux（但請不要這樣做！），並嘗試重啓 sshd，且這種方法能夠起效。但是， <code>semanage</code> 應用可以告訴我們在哪些端口上可以開啓 sshd 而不會出現任何問題。</p><p>運行：</p><pre><code># semanage port -l | grep ssh
</code></pre><p>便可以得到一個 SELinux 允許 sshd 在哪些端口上監聽的列表：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/SELinux-Permission.png" alt="Semanage 工具"></p><p><em>Semanage 工具</em></p><p>所以讓我們在 <code>/etc/ssh/sshd_config</code> 中將端口更改為 9998 端口，增加這個端口到 ssh_port_t 的上下文，然後重啓 sshd 服務：</p><pre><code># semanage port -a -t ssh_port_t -p tcp 9998
# systemctl restart sshd
# systemctl is-active sshd
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Semenage-Add-Port.png" alt="Semanage 添加端口"></p><p><em>semanage 添加端口</em></p><p>如你所見，這次 sshd 服務被成功地開啓了。這個例子告訴我們一個事實：SELinux 用它自己的端口類型的內部定義來控制 TCP 端口號。</p><p><strong>例 2：允許 httpd 訪問 sendmail</strong></p>`,22)),n("p",null,[e[11]||(e[11]=t("這是一個 SELinux 管理一個進程來訪問另一個進程的例子。假如在你的 RHEL 7 服務器上，",-1)),i(s,{href:"https://linux.cn/article-5639-1.html"},{default:p(()=>[...e[10]||(e[10]=[t("你要為 Apache 配置 mod_security 和 mod_evasive",-1)])]),_:1}),e[12]||(e[12]=t("，你需要允許 httpd 訪問 sendmail，以便在遭受到 (D)DoS 攻擊時能夠用郵件來提醒你。在下面的命令中，如果你不想使得更改在重啓後仍然生效，請去掉 ",-1)),e[13]||(e[13]=n("code",null,"-P",-1)),e[14]||(e[14]=t(" 選項。",-1))]),e[36]||(e[36]=o(`<pre><code># semanage boolean -1 | grep httpd_can_sendmail
# setsebool -P httpd_can_sendmail 1
# semanage boolean -1 | grep httpd_can_sendmail
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Allow-Apache-to-Send-Mails.png" alt="允許 Apache 發送郵件"></p><p><em>允許 Apache 發送郵件</em></p><p>從上面的例子中，你可以知道 SELinux 布爾設定（或者只是布爾值）分別對應於 true 或 false，被嵌入到了 SELinux 策略中。你可以使用 <code>semanage boolean -l</code> 來列出所有的布爾值，也可以管道至 grep 命令以便篩選輸出的結果。</p><p><strong>例 3：在一個特定目錄而非默認目錄下提供一個靜態站點服務</strong></p><p>假設你正使用一個不同於默認目錄（<code>/var/www/html</code>）的目錄來提供一個靜態站點服務，例如 <code>/websites</code> 目錄（這種情形會出現在當你把你的網絡文件存儲在一個共享網絡設備上，並需要將它掛載在 /websites 目錄時）。</p><p>a). 在 /websites 下創建一個 index.html 文件並包含如下的內容：</p><pre><code>&lt;html&gt;
&lt;h2&gt;SELinux test&lt;/h2&gt;
&lt;/html&gt;
</code></pre><p>假如你執行</p><pre><code># ls -lZ /websites/index.html
</code></pre><p>你將會看到這個 index.html 已經被標記上了 default_t SELinux 類型，而 Apache 不能訪問這類文件：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Check-File-Permssion.png" alt="檢查 SELinux 文件的權限"></p><p><em>檢查 SELinux 文件的權限</em></p><p>b). 將 <code>/etc/httpd/conf/httpd.conf</code> 中的 DocumentRoot 改為 /websites，並不要忘了 更新相應的 Directory 塊。然後重啓 Apache。</p><p>c). 瀏覽 <code>http://&lt;web server IP address&gt;</code>，則你應該會得到一個 503 Forbidden 的 HTTP 響應。</p><p>d). 接下來，遞歸地改變 /websites 的標誌，將它的標誌變為 <code>httpd_sys_content_t</code> 類型，以便賦予 Apache 對這些目錄和其內容的只讀訪問權限：</p><pre><code># semanage fcontext -a -t httpd_sys_content_t &quot;/websites(/.*)?&quot;
</code></pre><p>e). 最後，應用在 d) 中創建的 SELinux 策略：</p><pre><code># restorecon -R -v /websites
</code></pre><p>現在重啓 Apache 並再次瀏覽到 <code>http://&lt;web server IP address&gt;</code>，則你可以看到被正確展現出來的 html 文件：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/08part13.png" alt="確認 Apache 頁面"></p><p><em>確認 Apache 頁面</em></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>在本文中，我們詳細地介紹了 SELinux 的基礎知識。請注意，由於這個主題的廣泛性，在單篇文章中做出一個完全詳盡的解釋是不可能的，但我們相信，在這個指南中列出的基本原則將會對你進一步瞭解更高級的話題有所幫助，假如你想了解的話。</p>`,24)),n("p",null,[e[17]||(e[17]=t("假如可以，請讓我推薦兩個必要的資源來入門 SELinux：",-1)),i(s,{href:"https://www.nsa.gov/research/selinux/index.shtml"},{default:p(()=>[...e[15]||(e[15]=[t("NSA SELinux 頁面",-1)])]),_:1}),e[18]||(e[18]=t(" 和 ",-1)),i(s,{href:"https://access.redhat.com/documentation/en-US/Red_Hat_Enterprise_Linux/7/html/SELinux_Users_and_Administrators_Guide/part_I-SELinux.html"},{default:p(()=>[...e[16]||(e[16]=[t("針對用户和系統管理員的 RHEL 7 SELinux 指南",-1)])]),_:1}),e[19]||(e[19]=t("。",-1))]),e[37]||(e[37]=n("p",null,"假如你有任何的問題或評論，請不要猶豫，讓我們知曉吧。",-1)),e[38]||(e[38]=n("hr",null,null,-1)),n("p",null,[e[21]||(e[21]=t("via: ",-1)),i(s,{href:"http://www.tecmint.com/selinux-essentials-and-control-filesystem-access/"},{default:p(()=>[...e[20]||(e[20]=[t("http://www.tecmint.com/selinux-essentials-and-control-filesystem-access/",-1)])]),_:1})]),n("p",null,[e[25]||(e[25]=t("作者：",-1)),i(s,{href:"http://www.tecmint.com/author/gacanepa/"},{default:p(()=>[...e[22]||(e[22]=[t("Gabriel Cánepa",-1)])]),_:1}),e[26]||(e[26]=t(" 譯者：",-1)),i(s,{href:"https://github.com/FSSlc"},{default:p(()=>[...e[23]||(e[23]=[t("FSSlc",-1)])]),_:1}),e[27]||(e[27]=t(" 校對：",-1)),i(s,{href:"https://github.com/wxy"},{default:p(()=>[...e[24]||(e[24]=[t("wxy",-1)])]),_:1})]),n("p",null,[e[30]||(e[30]=t("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[28]||(e[28]=[t("LCTT",-1)])]),_:1}),e[31]||(e[31]=t(" 原創翻譯，",-1)),i(s,{href:"https://linux.cn/"},{default:p(()=>[...e[29]||(e[29]=[t("Linux中國",-1)])]),_:1}),e[32]||(e[32]=t(" 榮譽推出",-1))])])}const h=r(u,[["render",S]]);export{f as __pageData,h as default};
